var n=`0266-cevapi`;var t=`world-0266`;var o=`HR`;var r=`southern-europe`;var a=4;var l=61;var s={en:`Ćevapi`,ua:`Чевапі`};var d={en:`A traditional Croatia dish made with ground beef, ground lamb, yellow onion, garlic. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Хорватія. Основні інгредієнти: яловичий фарш, фарш з ягнятини, жовта цибуля, часник. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`ground-beef`,320,`g`],[`ground-lamb`,330,`g`],[`yellow-onion`,100,`g`],[`garlic`,3,`clove`],[`sweet-paprika`,4,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 35 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 35 хвилин.`,t:[`rapid-chilling`],m:35,i:[]},{en:`Grill over medium-high heat for about 12 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 12 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:12,i:[[`extra-virgin-olive-oil`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`pita-bread`,250,`g`],[`red-onion`,80,`g`]]}];var u={slug:n,id:t,country:`HR`,region:r,servings:4,minutes:61,title:s,text:d,steps:g};export{o as country,u as default,t as id,l as minutes,r as region,a as servings,n as slug,g as steps,d as text,s as title};